'use strict';
const BikeEngine={
 decode(data){return data.rows.map(row=>Object.fromEntries(data.columns.map((k,i)=>[k,row[i]])));},
 filter(rows,f){return rows.filter(r=>r.collision_year>=f.from&&r.collision_year<=f.to&&['make','category','band','style','age'].every(k=>!f[k]||f[k]==='all'||r[k]===f[k])&&(!f.role||f.role==='all'||r.casualty_class===+f.role)&&(!f.search||r.model.toLowerCase().includes(f.search.toLowerCase()))&&(!f.cc||r.cc===+f.cc));},
 sum(rows){return rows.reduce((s,r)=>{for(const k of ['n','fatal','ksi','adj'])s[k]+=r[k];return s;},{n:0,fatal:0,ksi:0,adj:0});},
 metric(r,key){return key==='share'?(r.n?100*r.ksi/r.n:0):r[key];},
 group(rows,keys){const map=new Map();for(const r of rows){const key=JSON.stringify(keys.map(k=>r[k]));if(!map.has(key))map.set(key,{...Object.fromEntries(keys.map(k=>[k,r[k]])),n:0,fatal:0,ksi:0,adj:0});let s=map.get(key);for(const k of ['n','fatal','ksi','adj'])s[k]+=r[k];}return [...map.values()];},
 rank(rows,metric,min=0){return this.group(rows,['make','model','band','style']).filter(r=>r.n>=Math.max(min,metric==='share'?50:0)).sort((a,b)=>this.metric(b,metric)-this.metric(a,metric)||b.n-a.n||a.model.localeCompare(b.model));},
 csv(rows,scope,adjustedAvailable){const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';return '\uFEFF'+[['Scope',scope],['Measure note','KSI percentage is among casualties, not risk per mile. Curated types are incomplete.'],['Model family','Capacity band','Curated type','All casualties','Fatal','Recorded KSI','Adjusted KSI','KSI % among casualties'],...rows.map(r=>[r.model,r.band,r.style,r.n,r.fatal,r.ksi,adjustedAvailable?r.adj.toFixed(2):'Unavailable when 2020 included',(100*r.ksi/r.n).toFixed(2)])].map(row=>row.map(quote).join(',')).join('\r\n');}
};
if(typeof module!=='undefined')module.exports=BikeEngine;
if(typeof document!=='undefined'){
 const $=id=>document.getElementById('b-'+id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=new Intl.NumberFormat('en-GB',{maximumFractionDigits:0}),dec=new Intl.NumberFormat('en-GB',{maximumFractionDigits:1});
 let rows=[],selected=[],ranking=[],scope='',detail=null;
 const controls=['from','to','make','category','band','style','age','role','search','cc','metric'];
 const ages=['Under 16','16–19','20–24','25–34','35–44','45–54','55–64','65+','Unknown age'];
 const order=['≤50cc','51–125cc','126–500cc','>500cc','501–750cc','751–1000cc','>1000cc','Electric','Other / unknown','Unknown capacity'];
 function options(id,items,all=true){$(id).innerHTML=(all?'<option value="all">All</option>':'')+items.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');}
 function pct(a,b){return b?dec.format(100*a/b)+'%':'—';}
 function table(headers,rs){return '<table><thead><tr>'+headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rs.map(row=>'<tr>'+row.map((x,i)=>i?'<td>'+esc(x)+'</td>':'<th scope="row">'+esc(x)+'</th>').join('')+'</tr>').join('')+'</tbody></table>';}
 function charts(key){const metric=$('metric').value,groups=BikeEngine.group(selected,[key]).sort((a,b)=>BikeEngine.metric(b,metric)-BikeEngine.metric(a,metric));const max=Math.max(1,...groups.filter(g=>metric!=='share'||g.n>=50).map(g=>BikeEngine.metric(g,metric)));$(key+'-chart').innerHTML=groups.length?'<div class="bars">'+groups.map(g=>{const enough=metric!=='share'||g.n>=50,v=BikeEngine.metric(g,metric);return `<div class="bar-row"><span class="bar-name">${esc(g[key])}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="width:${enough?v/max*100:0}%"></div></div><span class="bar-value">${enough?(metric==='share'?dec.format(v)+'%':num.format(v)):'—'}<small>${enough?num.format(g.n)+' casualties':'Below 50 casualties'}</small></span></div>`;}).join('')+'</div>':'<p>No matching casualties.</p>';}
 function ageGroups(){return BikeEngine.group(selected,[$('cross').value,'age']);}
 function renderAge(){
  const key=$('cross').value,metric=$('metric').value,g=ageGroups(),labels=[...new Set(g.map(r=>r[key]))];
  labels.sort((a,b)=>key==='style'?a.localeCompare(b):order.indexOf(a)-order.indexOf(b));
  const max=Math.max(1,...g.filter(r=>metric!=='share'||r.n>=50).map(r=>BikeEngine.metric(r,metric)));
  const cellMap=new Map(g.map(r=>[JSON.stringify([r[key],r.age]),r]));
  $('age-note').textContent=$('role').value==='1'?'Riders only: age is the injured rider’s age.':$('role').value==='2'?'Passengers only: age is the injured passenger’s age, not the rider’s age.':'Riders and passengers combined: age is each injured person’s age. Select riders only to examine rider age.';
  $('matrix').innerHTML=g.length?'<table class="age-matrix"><thead><tr><th scope="col">Motorcycle group / age</th>'+ages.map(a=>'<th scope="col">'+esc(a)+'</th>').join('')+'</tr></thead><tbody>'+labels.map(label=>'<tr><th scope="row">'+esc(label)+'</th>'+ages.map(age=>{const r=cellMap.get(JSON.stringify([label,age]));if(!r)return '<td>—<small>No casualties</small></td>';const enough=metric!=='share'||r.n>=50,v=BikeEngine.metric(r,metric);return '<td style="background:rgba(255,187,0,'+(enough?(.08+.65*v/max):0)+')">'+(enough?(metric==='share'?dec.format(v)+'%':num.format(v)):'Withheld')+'<small>'+num.format(r.n)+' casualties</small></td>';}).join('')+'</tr>').join('')+'</tbody></table>':'<p>No matching casualties.</p>';
  const ranked=g.filter(r=>metric!=='share'||r.n>=50).sort((a,b)=>BikeEngine.metric(b,metric)-BikeEngine.metric(a,metric)||b.n-a.n);
  $('age-ranking').innerHTML=table(['Motorcycle group','Age','Casualties','Recorded KSI','Fatal','Selected measure'],ranked.slice(0,15).map(r=>[r[key],r.age,num.format(r.n),num.format(r.ksi),num.format(r.fatal),metric==='share'?pct(r.ksi,r.n):num.format(BikeEngine.metric(r,metric))]));
  $('age-export').disabled=!g.length;
 }
 $('age-export').addEventListener('click',()=>{const key=$('cross').value,metric=$('metric').value,quote=v=>'"'+String(v).replace(/"/g,'""')+'"';const content=[['Scope',scope],['Age definition',$('age-note').textContent],['Measure',metric],['Motorcycle group','Age','Casualties','Recorded KSI','Fatal','Selected measure'],...ageGroups().map(r=>[r[key],r.age,r.n,r.ksi,r.fatal,metric==='share'&&r.n<50?'Withheld: fewer than 50 casualties':BikeEngine.metric(r,metric)])].map(row=>row.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='motorcycles-by-age.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 function renderDetail(){if(!detail){$('detail').hidden=true;return;}const subset=selected.filter(r=>r.model===detail);$('detail').hidden=false;$('detail-title').textContent=detail+' · recorded engine capacities';$('detail-table').innerHTML=table(['Engine cc','All casualties','Fatal','Recorded KSI','KSI %'],BikeEngine.group(subset,['cc']).sort((a,b)=>b.ksi-a.ksi).map(r=>[r.cc<0?'Unknown':r.cc,num.format(r.n),num.format(r.fatal),num.format(r.ksi),pct(r.ksi,r.n)]));}
 function render(){let from=+$('from').value,to=+$('to').value,note='';if($('metric').value==='adj'&&from<2021){from=2021;$('from').value='2021';note='Adjusted estimates start in 2021; the start year has been moved. ';}if(to<from){to=from;$('to').value=String(to);}const f=Object.fromEntries(controls.map(k=>[k,$(k).value]));f.from=from;f.to=to;selected=BikeEngine.filter(rows,f);const s=BikeEngine.sum(selected),known=BikeEngine.sum(selected.filter(r=>r.style!=='Unclassified / ambiguous')),unknown=BikeEngine.sum(selected.filter(r=>r.model==='Unknown / redacted'));scope=`${from}–${to} · ${['make','category','band','style','age','role'].filter(k=>f[k]!=='all').map(k=>k==='role'?(f[k]==='1'?'Riders':'Passengers'):f[k]).concat(f.search?['Family contains '+f.search]:[],f.cc?[f.cc+'cc']:[]).join(' · ')||'All makes, categories and types; riders and passengers'}`;
 $('status').textContent=note+scope+(s.n?'':' · No matching casualties');
 $('kpis').innerHTML=[['All casualties',num.format(s.n)],['Recorded KSI',num.format(s.ksi)],['Fatal casualties',num.format(s.fatal)],['KSI among casualties',pct(s.ksi,s.n)]].map(([label,value])=>`<div class="kpi"><span>${label}</span><strong>${value}</strong></div>`).join('');
 $('coverage').textContent=`Type assigned for ${pct(known.n,s.n)} of selected casualties (${num.format(known.n)} of ${num.format(s.n)}); ${pct(known.ksi,s.ksi)} of selected recorded KSI. Make and model both unavailable for ${pct(unknown.n,s.n)} of selected casualties. Unclassified is retained; type rankings describe only the curated subset.`;
 $('measure').textContent=$('metric').value==='share'?'Charts and table rank recorded KSI as a percentage of casualties, requiring at least 50 casualties per group. This is not a risk or crash probability.':$('metric').value==='adj'?'Charts and table rank adjusted KSI estimates (rounded for display). Top cards retain recorded counts. Estimates account for reporting-system changes, not exposure or confounding.':'Charts and table rank '+($('metric').value==='fatal'?'fatal casualties':$('metric').value==='n'?'all casualties':'recorded KSI')+'. Recorded serious-injury counts are affected by changes in severity reporting.';
 for(const key of ['category','band','style'])charts(key);
 renderAge();
 ranking=BikeEngine.rank(selected,$('metric').value,+$('min').value);
 $('table').innerHTML=ranking.length?`<p>${num.format(ranking.length)} qualifying rows · showing ${Math.min(50,ranking.length)}</p><table><thead><tr>${['Model family','Capacity','Curated type','Casualties','Fatal','Recorded KSI','Adjusted KSI','KSI %'].map(x=>'<th scope="col">'+esc(x)+'</th>').join('')}</tr></thead><tbody>`+ranking.slice(0,50).map((r,i)=>`<tr><th scope="row"><button type="button" class="model-button" data-row="${i}">${esc(r.model)}</button></th><td>${esc(r.band)}</td><td>${esc(r.style)}</td><td>${num.format(r.n)}</td><td>${num.format(r.fatal)}</td><td>${num.format(r.ksi)}</td><td>${from>=2021?num.format(r.adj):'—'}</td><td>${pct(r.ksi,r.n)}</td></tr>`).join('')+'</tbody></table>':'<p>No rows meet the filters and minimum casualty count.</p>';
 $('export').disabled=!ranking.length;renderDetail();
 }
 function reset(){for(const k of ['make','category','band','style','age'])$(k).value='all';$('role').value='1';$('cross').value='category';$('from').value='2020';$('to').value='2025';$('search').value='';$('cc').value='';$('metric').value='ksi';$('min').value='0';detail=null;}
 $('filters').addEventListener('submit',e=>e.preventDefault());$('filters').addEventListener('input',()=>{detail=null;render();});$('min').addEventListener('change',render);$('cross').addEventListener('change',render);$('reset').addEventListener('click',()=>{reset();render();});
 $('table').addEventListener('click',e=>{const b=e.target.closest('[data-row]');if(!b)return;detail=ranking[+b.dataset.row].model;renderDetail();$('detail').scrollIntoView({behavior:'smooth',block:'start'});});
 document.querySelectorAll('[data-preset]').forEach(b=>{b.disabled=true;b.addEventListener('click',()=>{reset();const p=b.dataset.preset;if(p==='large')$('category').value='>500cc';if(p==='small')$('category').value='51–125cc';if(p==='moped')$('category').value='≤50cc';if(p==='medium')$('category').value='126–500cc';if(p==='electric')$('category').value='Electric';render();document.getElementById('comparison').scrollIntoView({behavior:'smooth',block:'start'});});});
 $('export').addEventListener('click',()=>{const blob=new Blob([BikeEngine.csv(ranking,scope,+$('from').value>=2021)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='motorcycles-and-age-model-comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 (async()=>{try{const response=await fetch('data/bikes.json');if(!response.ok)throw Error('Could not load comparison data');const data=await response.json();rows=BikeEngine.decode(data);options('from',[2020,2021,2022,2023,2024,2025],false);options('to',[2020,2021,2022,2023,2024,2025],false);for(const key of ['make','category','band','style','age']){const values=[...new Set(rows.map(r=>r[key]))];values.sort((a,b)=>key==='category'||key==='band'?order.indexOf(a)-order.indexOf(b):a.localeCompare(b));options(key,key==='age'?ages:values);}
 $('mapping').innerHTML='<table><thead><tr><th>Recorded family label</th><th>Assigned type</th><th>Basis</th></tr></thead><tbody>'+data.mapping.map(m=>`<tr><td>${esc(m.model)}</td><td>${esc(m.style)}</td><td><a href="${esc(data.sources[m.source])}">Manufacturer reference</a></td></tr>`).join('')+'</tbody></table>';
 for(const id of controls.concat(['reset']))$(id).disabled=false;document.querySelectorAll('[data-preset]').forEach(b=>b.disabled=false);reset();render();}catch(e){$('error').hidden=false;$('error').textContent='The comparison could not load. Please refresh the page. '+e.message;$('status').textContent='Comparison unavailable';}})();
}
